  String message(String value) {
    for (final item in _lateMessages) {
      final chineseMatch = item.pattern.firstMatch(value);
      final match = chineseMatch ?? item.englishPattern.firstMatch(value);
      if (match != null) {
        final source = chineseMatch == null ? item.english : item.chinese;
        final indexes = RegExp(
          r'\{arg(\d+)\}',
        ).allMatches(source).map((m) => int.parse(m[1]!)).toList();
        final args = List<Object?>.filled(match.groupCount, '');
        for (var i = 0; i < indexes.length; i++) {
          args[indexes[i]] = message(match[i + 1]!);
        }
        return _format(isEnglish ? item.english : item.chinese, args);
      }
    }
    return value;
  }
}

class _LateMessage {
  _LateMessage(this.chinese, this.english)
    : pattern = _pattern(chinese),
      englishPattern =
          english.replaceAll(RegExp(r'\{arg\d+\}'), '').trim().isEmpty
          ? RegExp(r'(?!)')
          : _pattern(english);
  static RegExp _pattern(String source) => RegExp(
    '^' +
        source
            .split(RegExp(r'\{arg\d+\}'))
            .map(RegExp.escape)
            .join(r'([\s\S]*?)') +
        r'$',
  );
  final RegExp pattern, englishPattern;
  final String chinese, english;
}

